const app=document.querySelector('#app');
const KEY='pocket-story-v2-ch1';
const defaultState={started:false,phase:'present',view:'lock',perspective:'seulgi',seen:[],classified:{},unlocked:false};
let state={...defaultState,...JSON.parse(localStorage.getItem(KEY)||'{}')};
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const anchors=['told-before','family-gap','europe-memory'];
const ready=()=>anchors.every(x=>state.classified[x]==='fact')&&state.classified['found-out-online']==='false';
const count=()=>anchors.filter(x=>state.classified[x]==='fact').length+(state.classified['found-out-online']==='false'?1:0);
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function go(view){state.view=view;save();render();}
function mark(id,value){state.seen=[...new Set([...state.seen,id])];state.classified[id]=value;if(ready())state.unlocked=true;save();render();toast(state.unlocked?'另一份设备记录已解锁':'已加入探索手记');}
function toast(msg){const n=document.createElement('div');n.className='toast';n.textContent=msg;document.body.append(n);setTimeout(()=>n.remove(),1800)}
function shell(title,body,back='home'){return `<section class="story-view"><header class="top"><button data-go="${back}">‹ 返回</button><strong>${title}<small>${state.perspective==='seulgi'?'当前记录：涩琪':'当前记录：柱现'}</small></strong><button data-go="notebook">手记</button></header><div class="content">${body}</div></section>`}
function splash(){return `<section class="story-view splash"><small>FICTIONAL INTERACTIVE STORY</small><h1>the same blank</h1><p>根据公开活动构建的虚构叙事。<br>私人对话、人物关系与情节均为创作。<br><br>记录可以被看见，真相未必可以。</p><button class="primary" data-start>打开记录</button></section>`}
function lock(){return `<section class="story-view lock"><div class="date">10月20日 星期二</div><div class="time">23:06</div><button class="notice" data-open="kkt"><i style="background:#f8df27;color:#111">T</i><span><strong>KakaoTalk</strong><span>队长老师：回酒店了吗？</span></span></button><button class="notice" data-open="instagram"><i>◎</i><span><strong>Instagram</strong><span>新的巡演内容</span></span></button><button class="notice" data-open="pann"><i style="background:#f43d55">판</i><span><strong>Pann</strong><span>巡演空档期，她们是不是完全各玩各的？</span></span></button><button class="soft unlock" data-go="home">打开手机　⌃</button></section>`}
function home(){const who=state.perspective==='seulgi'?'涩琪的记录':'柱现的记录';return `<section class="story-view home"><div class="widget"><small>THE SAME BLANK · CHAPTER 01</small><strong>${state.phase==='present'?'10月20日':'the same blank'}</strong><span>${who} · ${state.phase==='present'?'现在':'9月28日'}</span></div><div class="apps">${appIcon('kkt','T','KakaoTalk')}${appIcon('instagram','◎','Instagram')}${appIcon('pann','판','Pann')}${appIcon('archive','▤','记录')}${appIcon('notebook','☰','探索手记')}${appIcon('switch','⇄','切换设备')}</div></section>`}
function appIcon(view,icon,label){return `<button class="app" data-view="${view}"><span class="app-icon">${icon}</span>${label}</button>`}
function evidence(id,label){const done=state.classified[id];return `<div class="choice-row"><button class="${done==='fact'?'on':''}" data-mark="${id}:fact">${label||'记录为事实'}</button><button class="${done==='unclear'?'on':''}" data-mark="${id}:unclear">尚无法确认</button><button class="${done==='false'?'on':''}" data-mark="${id}:false">可能不实</button></div>`}
function kkt(){let body;if(state.phase==='present'){body=`<div class="chat-date">10月20日 · 广岛之后</div><div class="bubble them">回酒店了吗？<time>23:05</time></div><div class="bubble me">刚回来<time>23:06</time></div><div class="bubble them">嗯<time>23:06</time></div><div class="question">这三句话看起来冷淡吗？还是只是一次普通的行程确认？当前记录无法回答。</div>`}else if(state.perspective==='seulgi'){body=`<div class="chat-date">9月28日 · 仙台公演之后</div><div class="bubble me">休息的时候有什么安排吗<time>20:41</time></div><div class="bubble them">和妈妈出去几天<time>20:44</time></div><div class="bubble me">去哪里<time>20:44</time></div><div class="bubble them">意大利<time>20:45</time></div><div class="bubble me">真好<br>好好玩<time>20:47</time></div><div class="bubble them">嗯<time>20:49</time></div><div class="card"><span class="source">虚构私人记录</span><h3>她是在偶遇消息出现前知道的吗？</h3><p>聊天日期早于10月公开流传的目击信息。</p>${evidence('told-before','提前知情是确定事实')}</div>`}else{body=`<div class="chat-date">9月28日 · 同一段对话</div><div class="bubble them">休息的时候有什么安排吗<time>20:41</time></div><div class="bubble me">和妈妈出去几天<time>20:44</time></div><div class="bubble them">去哪里<time>20:44</time></div><div class="bubble me">意大利<time>20:45</time></div><div class="bubble them">真好<br>好好玩<time>20:47</time></div><div class="bubble me">嗯<time>20:49</time></div><div class="card"><span class="source">虚构私人记录</span><p>交换设备没有出现新的解释。同一段话换了一侧显示，仍然只是一段话。</p></div>`}return shell('KakaoTalk',body)}
function instagram(){const body=`<article class="card"><span class="source">公开原始内容</span><h2>记录习惯不同</h2><p>涩琪持续发布旅行、城市和自己的状态；柱现留下的即时公开内容更少。信息数量不同，不等于投入程度不同。</p></article><article class="card"><span class="source">2025 · 官方Vlog</span><h3>涩琪与母亲的欧洲旅行</h3><p>公开视频记录了与母亲前往哥本哈根、布拉格的长途旅行。</p><p class="links"><a href="https://www.youtube.com/watch?v=PV5Rfz6iUSk" target="_blank" rel="noreferrer">查看公开来源 ↗</a></p>${evidence('family-gap','家庭旅行是公开事实')}</article><article class="card"><span class="source">2023 · 官方Vlog</span><h3>过去的欧洲巡演记忆</h3><p>欧洲巡演期间，两人共同出现的非工作片段被官方Vlog记录下来。它能证明过去留下过共同记忆，不能证明现在的关系。</p><p class="links"><a href="https://www.youtube.com/watch?v=RtGSAdY-9qQ" target="_blank" rel="noreferrer">查看公开来源 ↗</a></p>${evidence('europe-memory','共同Vlog存在是事实')}</article>`;return shell('Instagram · 公开存档',body)}
function pann(){const body=`<article class="card"><span class="source">论坛转述 · 未完全核实</span><h1 class="post-title">巡演空档期，她们是不是完全各玩各的？</h1><p>仙台之后到广岛中间有一段时间。涩琪还是照常发自己的东西，柱现那边几乎没动静，后来又有人说在意大利见到她和妈妈。</p></article><div class="comment"><b>雨后的站台</b><p>她们以前欧洲巡演不是一起玩得挺开心的吗？Vlog里都有。</p></div><div class="comment"><b>慢慢散场</b><p>以前是以前。现在各自陪家人，也不能直接推成关系不好。</p></div><div class="comment"><b>记录不是答案</b><p>涩琪本来就喜欢拍，柱现本来就不太发。不能按发帖数量比较感情。</p></div><div class="comment"><b>匿名</b><p>涩琪应该也是看见偶遇图以后，才知道柱现去了意大利吧。</p>${evidence('found-out-online','判断这条说法')}</div><div class="comment"><b>旧欧洲地图</b><p>但重点或许不是谁陪妈妈旅行，而是她们很久没有留下工作以外的共同记录。</p></div>`;return shell('Pann · 讨论',body)}
function archive(){const body=`<h2>巡演记录</h2><p class="muted">有人反复提到这段没有演出的时间。</p><div class="timeline"><div class="moment locked"><b>8月</b><p>团队回归</p></div><div class="moment locked"><b>9月19—27日</b><p>福冈 · 神户 · 大阪 · 仙台</p></div><div class="moment active"><button data-gap><b>9月28日—10月17日</b><p>空白 · 点击进入第一章</p></button></div><div class="moment locked"><b>10月18—24日</b><p>广岛 · 爱知</p></div><div class="moment locked"><b>11月4—5日</b><p>横滨</p></div></div>`;return shell('记录 / Archive',body)}
function notebook(){const pct=Math.round(count()/4*100);const body=`<h2>第一章 · the same blank</h2><p>找到3个事实锚点，并识别1条与记录矛盾的说法，才能打开另一部设备。</p><div class="progress"><i style="width:${pct}%"></i></div><p>${count()} / 4 已确认</p>${noteRow('told-before','涩琪是否提前知道旅行？')}${noteRow('family-gap','家庭旅行是否有公开依据？')}${noteRow('europe-memory','过去共同的欧洲Vlog是否存在？')}${noteRow('found-out-online','“她从网友那里才知道”可靠吗？')}<div class="question">一个人留下了很多记录，一个人几乎什么都没有留下。<br><br>记录的多少，是不是也代表在意的多少？</div>${state.unlocked?'<button class="primary" data-switch>切换到柱现的记录</button>':'<button class="soft" data-locked>另一份设备记录尚未解锁</button>'}`;return shell('探索手记',body)}
function noteRow(id,title){const v=state.classified[id];return `<div class="card"><b>${title}</b><p>${v==='fact'?'已归类：确定事实':v==='false'?'已归类：可能不实':v==='unclear'?'已归类：尚无法确认':'尚未找到对应记录'}</p></div>`}
function switchView(){if(!state.unlocked){toast('先完成第一章的4项判断');return}state.perspective=state.perspective==='seulgi'?'irene':'seulgi';state.phase='gap';save();go('home')}
function render(){const phone=document.querySelector('.phone-screen');if(phone)phone.dataset.view=!state.started?'splash':state.view==='lock'?'lock':state.view==='home'?'phonehome':'story';if(!state.started){app.innerHTML=splash();bind();return}const views={lock,home,kkt,instagram,pann,archive,notebook};app.innerHTML=(views[state.view]||home)();bind()}
function bind(){const homeButton=document.querySelector('#phone-home');if(homeButton)homeButton.onclick=()=>{if(state.started)go('home')};const desktopEnter=document.querySelector('#desktop-enter');if(desktopEnter)desktopEnter.onclick=()=>{state.started=true;state.view='lock';save();render()};app.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{state.started=true;state.view='lock';save();render()});app.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));app.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>go(b.dataset.open));app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>b.dataset.view==='switch'?switchView():go(b.dataset.view));app.querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{const [id,v]=b.dataset.mark.split(':');mark(id,v)});app.querySelectorAll('[data-gap]').forEach(b=>b.onclick=()=>{state.phase='gap';save();go('home');toast('第一章：the same blank')});app.querySelectorAll('[data-switch]').forEach(b=>b.onclick=switchView);app.querySelectorAll('[data-locked]').forEach(b=>b.onclick=()=>toast(`还需要确认 ${4-count()} 项`))}
render();
